from cats_k import ru_rule, ru_word


def k(id, group, en, ru, crit, lines, inv="", type="KNOWLEDGE", **kw):
    cat(id, type, group, en, ru, crit, crit, lines, inv, **kw)


def L(*xs):
    return "\n".join(xs)


